const input = $input.first().json;
const slotsIn = Array.isArray(input.slots) ? input.slots : [];
const busy = Array.isArray(input.busy_events) ? input.busy_events : [];
const prefer = input.preferred_period || 'any';
const avoidRain = input.avoid_rain === true;
const reqOutdoor = (input.is_outdoor === true || input.is_outdoor === false) ? input.is_outdoor : null;
const habit = Array.isArray(input.habit_hours) ? input.habit_hours.map(Number).filter(Number.isFinite) : [];
const warnings = Array.isArray(input.warnings) ? [...input.warnings] : [];
const RAIN_LIMIT = 60; // >= 60% (ngoai troi + avoid_rain) => khong phu hop

const OFFSET = 7 * 3600000, MIN = 60000, HOUR = 3600000, DAY = 86400000;
const toMs = (s) => new Date(String(s).replace(' ', 'T') + '+07:00').getTime();
const clamp = (x) => Math.max(0, Math.min(100, x));
const WINDOWS = { morning: [6, 12], afternoon: [12, 18], evening: [18, 22] };
const dayStartOf = (ms) => Math.floor((ms + OFFSET) / DAY) * DAY - OFFSET;
const busyMs = busy.map((b) => ({ s: toMs(b.start_time), e: toMs(b.end_time) })).filter((b) => Number.isFinite(b.s) && Number.isFinite(b.e));

// is_outdoor hieu luc: slot -> request -> (null & avoid_rain=true => ngoai troi)
const effOutdoor = (slot) => {
  if (slot.is_outdoor === true || slot.is_outdoor === false) return slot.is_outdoor;
  if (reqOutdoor !== null) return reqOutdoor;
  return avoidRain;
};
const sPeriod = (a, b) => {
  const w = WINDOWS[prefer];
  if (!w) return 100;
  const ds = dayStartOf(a);
  const overlap = Math.max(0, Math.min(b, ds + w[1] * HOUR) - Math.max(a, ds + w[0] * HOUR));
  return clamp(overlap / (b - a) * 100);
};
const sWeather = (slot) => {
  if (!avoidRain) return 100;
  if (!effOutdoor(slot)) return 100;
  const p = slot.rain_probability;
  if (p === null || p === undefined || !Number.isFinite(Number(p))) return 50; // chua co du lieu => trung tinh
  return clamp(100 - Number(p));
};
const sBuffer = (a, b) => {
  let before = Infinity, after = Infinity;
  for (const x of busyMs) {
    if (x.e <= a) before = Math.min(before, a - x.e);
    else if (x.s >= b) after = Math.min(after, x.s - b);
  }
  return clamp(Math.min(before, after) / MIN / 60 * 100); // >= 60 phut dem => 100
};
const sRest = (a) => {
  const ds = dayStartOf(a), de = ds + DAY;
  let load = 0;
  for (const x of busyMs) load += Math.max(0, Math.min(x.e, de) - Math.max(x.s, ds));
  load /= MIN; // phut ban trong ngay
  if (load <= 120) return 100;
  if (load >= 480) return 0;
  return clamp(100 - (load - 120) / 360 * 100);
};
const sHabit = (a) => {
  if (!habit.length) return 50;
  const d = new Date(a + OFFSET);
  const h = d.getUTCHours() + d.getUTCMinutes() / 60;
  const dist = Math.min(...habit.map((x) => Math.abs(h - x)));
  if (dist <= 0.5) return 100;
  if (dist <= 1.5) return 70;
  if (dist <= 2.5) return 40;
  return 20;
};

const scored = [];
for (const s of slotsIn) {
  const a = toMs(s.start_time), b = toMs(s.end_time);
  if (!Number.isFinite(a) || !Number.isFinite(b) || b <= a) continue;
  const outdoor = effOutdoor(s);
  const p = (s.rain_probability === null || s.rain_probability === undefined) ? null : Math.round(Number(s.rain_probability));
  const bd = { period: sPeriod(a, b), weather: sWeather(s), buffer: sBuffer(a, b), rest: sRest(a), habit: sHabit(a) };
  const total = 0.25 * bd.period + 0.25 * bd.weather + 0.20 * bd.buffer + 0.20 * bd.rest + 0.10 * bd.habit;
  const suitable = !(avoidRain && outdoor && p !== null && p >= RAIN_LIMIT);
  scored.push({
    a, b, start_time: s.start_time, end_time: s.end_time, is_outdoor: outdoor, rain_probability: p, is_suitable: suitable,
    score: Math.round(total * 100) / 100,
    score_breakdown: Object.fromEntries(Object.entries(bd).map(([k, v]) => [k, Math.round(v * 10) / 10]))
  });
}

let pool = scored.filter((x) => x.is_suitable);
if (pool.length === 0 && scored.length > 0) {
  pool = scored;
  warnings.push({ code: 'ALL_SLOTS_RAINY', message: 'Tat ca khung gio de xuat deu co xac suat mua cao (>= ' + RAIN_LIMIT + '%).' });
}
pool.sort((x, y) => y.score - x.score || x.a - y.a);

const picked = [];
const fits = (c, gap) => picked.every((p) => (c.a >= p.b || c.b <= p.a) && Math.abs(c.a - p.a) >= gap);
for (const c of pool) { if (picked.length >= 3) break; if (fits(c, 2 * HOUR)) picked.push(c); }   // da dang hoa: cach nhau >= 2h
for (const c of pool) { if (picked.length >= 3) break; if (!picked.includes(c) && fits(c, 0)) picked.push(c); }
picked.sort((x, y) => y.score - x.score || x.a - y.a);

const slots = picked.map((c, i) => ({
  slot_code: 'S' + (i + 1), start_time: c.start_time, end_time: c.end_time,
  is_outdoor: c.is_outdoor, rain_probability: c.rain_probability, is_suitable: c.is_suitable,
  score: c.score, score_breakdown: c.score_breakdown
}));
return [{ json: { has_slots: slots.length > 0, slots, total_candidates: scored.length, warnings } }];
